/** PushedPosition is where a client says a book was left. */
@Serializable
data class PushedPosition(
    val bookFileId: String,
    val position: String,
    val percent: Double? = null,
    /** ReadAt is when the reader was at this position, by the client's clock. */
    val readAt: String
)

/** ReaderManifest is everything the reader needs before it opens a book. */
@Serializable
data class ReaderManifest(
    val bookFileId: String,
    val format: String,
    val spine: List<SpineItem>,
    val toc: List<TOCEntry>
)

/** ReadingProgress is where a user has read to in one file. */
@Serializable
data class ReadingProgress(
    val bookFileId: String,
    /** Started is false when the book has never been opened, which is not an error and must not be treated as one. */
    val started: Boolean,
    /** Locator is the canonical position string, and is where the reader reopens. It is independent of font size, viewport, and device: a percentage would survive none of those. */
    val locator: String? = null,
    /** Percent renders Locator. Display only, never used to restore a position. */
    val percent: Double? = null,
    /** FurthestLocator is the deepest position reached, which may be ahead of Locator when the reader has turned back. It is what a "how far through am I?" figure is measured from, and it never moves backwards. */
    val furthestLocator: String? = null,
    val furthestPercent: Double? = null,
    val lastReadAt: String? = null
)

/** RecentAnnotation is a mark alongside the book it belongs to. */
@Serializable
data class RecentAnnotation(
    val annotation: Annotation,
    val bookFileId: String,
    val workId: String,
    val title: String,
    val format: String
)

/** RecentAnnotationList is the notes view across the whole library. */
@Serializable
data class RecentAnnotationList(
    val items: List<RecentAnnotation>,
    /** NextCursor continues the list from the last item; empty on the last page. */
    val nextCursor: String? = null
)

/** Recipient is somebody a book or notes are shared with: an id to change or end the share by, and the name to show. */
@Serializable
data class Recipient(
    val id: String,
    val username: String
)

/** RemoveForEveryoneRequest takes a book file off the installation for everybody and blocks its bytes from coming back. */
@Serializable
data class RemoveForEveryoneRequest(
    /** Reason is recorded on the blocklist, for administrators. Required; at most 1000 characters (and 4000 bytes). */
    val reason: String,
    /** PurgeQuotes also erases the file's words kept outside it: the text each highlight on it quotes, and the excerpt each chat citation of it keeps. The highlights, notes and citations themselves stay. Default false. */
    val purgeQuotes: Boolean? = null
)

/** RemovedForEveryone reports how many people's shelves the file left: its holders, and anybody whose upload of it was still waiting to be extracted. A count, not a list: who held a file is each of them's own business. */
@Serializable
data class RemovedForEveryone(
    val removedFor: Int
)

/** SaveProgress is the request body for recording a position. */
@Serializable
data class SaveProgress(
    val locator: String,
    val percent: Double? = null
)

/** Session is one live sign-in, as shown to the person who owns it. */
@Serializable
data class Session(
    val id: String,
    /** Current marks the session making this request, so a person can tell which row is the device in their hand before revoking one of the others. */
    val current: Boolean,
    /** UserAgent is the browser's own claim about itself. It is not verified and is shown only as a hint for recognising a device. */
    val userAgent: String? = null,
    /** ClientIP is the socket address the session was created from. */
    val clientIp: String? = null,
    /** Provider is how this session was authenticated: local, oidc, ldap, proxy. */
    val provider: String? = null,
    /** Device is set when this session is a bearer token held by a native client, and names it. Empty means a browser session in a cookie. */
    val device: String? = null,
    val createdAt: String,
    val lastUsedAt: String,
    val expiresAt: String
)

/** SessionList is every session that can still be used. */
@Serializable
data class SessionList(
    val items: List<Session>
)

/** SetupRequest creates the first account. */
@Serializable
data class SetupRequest(
    val username: String,
    val email: String? = null,
    val password: String
)

/** Share is one person's access to one book. */
@Serializable
data class Share(
    val userId: String,
    val username: String,
    /** CanDownload allows taking the original file rather than only reading it. */
    val canDownload: Boolean,
    /** Annotations is true when the owner's highlights and notes travel with it. */
    val annotations: Boolean
)

/** ShareActivity is one person's reading of one lent book on one day, named so the owner can tell which book it was without looking it up. */
@Serializable
data class ShareActivity(
    val bookFileId: String,
    val workId: String,
    val workTitle: String,
    val userId: String,
    val username: String,
    val day: String,
    val kind: String,
    val views: Int,
    val units: Int,
    val of: Int,
    /** Notable marks reading worth interrupting somebody for: most of a book in one day, or a whole-file download. */
    val notable: Boolean,
    val firstAt: String,
    val lastAt: String
)

/** ShareByUsername lends a book to the account with this username, for an installation that does not list its people to everybody. The name is matched without regard to case; the reply is the Share made, carrying the account's id for changing or ending it later. */
@Serializable
data class ShareByUsername(
    val username: String,
    val canDownload: Boolean,
    val annotations: Boolean
)

/** ShareList is everyone a book is shared with. */
@Serializable
data class ShareList(
    val items: List<Share>
)

/** ShareRequest sets one person's access to one book. */
@Serializable
data class ShareRequest(
    val canDownload: Boolean,
    val annotations: Boolean
)

/** SharingActivity is what has happened lately to the books this person lent. */
@Serializable
data class SharingActivity(
    val items: List<ShareActivity>,
    /** Notable counts the items worth acting on, so a client can decide whether to say anything without re-deriving the rule. */
    val notable: Int,
    /** Since is the start of the window these items cover. */
    val since: String
)

/** SignInLink is one link shown on the sign-in page. */
@Serializable
data class SignInLink(
    val label: String,
    /** Href is a path on this server, beginning with a single "/", or an https:// URL. Nothing else is accepted when the server starts. */
    val href: String
)

/** Source is one passage an answer was built from. */
@Serializable
data class Source(
    /** Number is the citation marker in the answer: [1], [2]. */
    val number: Int,
    /** Cited is false for a passage that was retrieved but not referred to. It is still shown, because it is part of why the answer says what it says. */
    val cited: Boolean,
    val workId: String,
    val bookFileId: String,
    val title: String,
    /** Label is the readable source: the book, the chapter, the page. */
    val label: String,
    val chapter: String? = null,
    /** Locator opens the reader at this passage. */
    val locator: String,
    val excerpt: String,
    val score: Double,
    /** FoundBy is "meaning", "keyword", or "both" - which arm of the search found this passage. Useful when an answer is wrong. */
    val foundBy: String? = null,
    /** Kind is "passage" or "note". A note is something the reader wrote in the margin of one of these books, and showing it as though the book had said it would misattribute their own opinion to an author. */
    val kind: String? = null
)

/** SpineContent is one document, sanitised and ready to insert into the DOM. */
@Serializable
data class SpineContent(
    val index: Int,
    /** HTML is a fragment, not a document: the reader supplies the page and the typography. The book's own stylesheet is deliberately not included. */
    val html: String
)

/** SpineItem is one document in reading order. */
@Serializable
data class SpineItem(
    val index: Int,
    val id: String? = null,
    /** Linear is false for supplementary content a reader may skip. It keeps its index regardless, because dropping it would renumber every locator after it. */
    val linear: Boolean
)

/** StartEnrichment optionally bounds one enrichment run. */
@Serializable
data class StartEnrichment(
    val limit: Int? = null
)

/** Stats summarises the library. */
@Serializable
data class Stats(
    val works: Int,
    val files: Int,
    val authors: Int,
    val tags: Int,
    val pages: Int,
    val missing: Int,
    val needsOcr: Int,
    val failed: Int,
    val byFormat: Map<String, Int>,
    /** QueueBusy is the number of pending and running jobs. Non-zero means the library is still filling up. */
    val queueBusy: Int
)

/** Subject is one thing a library is about, and how much of it. */
@Serializable
data class Subject(
    val name: String,
    /** Slug is what the shelf filters on: /?tag=<slug>. */
    val slug: String,
    val books: Int
)

/** SubjectList is everything this person's library is about, commonest first. */
@Serializable
data class SubjectList(
    val items: List<Subject>
)

/** Suggestion is something a model proposed, awaiting a person's decision. */
@Serializable
data class Suggestion(
    val id: String,
    val workId: String,
    val workTitle: String,
    /** Field is what is being proposed: title, summary, series, subjects, audience. */
    val field: String,
    /** Value is the proposal itself, shaped by the field. */
    val value: JsonElement,
    /** Current is what the work holds now, so the two can be compared. Empty when the field has no value, which is the case the proposal fills. */
    val current: String? = null,
    /** Model and PromptID are the provenance: which model, on which prompt. Shown to the user, because "the AI said so" is not a reason on its own. */
    val model: String? = null,
    val promptId: String? = null,
    val confidence: Double? = null,
    val generatedAt: String
)

/** SuggestionList is everything awaiting review. */
@Serializable
data class SuggestionList(
    val items: List<Suggestion>
)

/** SyncPosition is where a book was left, in both senses. */
@Serializable
data class SyncPosition(
    val bookFileId: String,
    /** Position is where the reader is, which moves in both directions. */
    val position: String,
    /** Furthest is how far they have got, which only ever advances. */
    val furthest: String,
    val percent: Double? = null,
    val furthestPercent: Double? = null,
    val readAt: String,
    val updatedAt: String
)

/** SyncPull is everything that changed for one reader since a moment. */
@Serializable
data class SyncPull(
    /** Until is the SERVER's clock at the moment of THIS read. Store it as the next `since` only once More comes back false and the round is done - while paging with Cursor, every page's Until is a different, earlier moment and none of them are the right one to keep. Never the client's own clock: two clocks a minute apart would silently lose or repeat a minute of somebody's reading. */
    val until: String,
    /** More says a page was filled and the rest is waiting. A client must page through with Cursor - not by resending the same `since` - before using Until, or it will skip what it did not receive. */
    val more: Boolean,
    /** Cursor resumes exactly where this page left off. Present whenever More is true; send it back as the `cursor` query parameter on the next call. Opaque - a client only ever echoes what it was given, never builds one. */
    val cursor: String? = null,
    val annotations: List<Annotation>,
    /** Deleted is the marks that are gone. A deletion cannot be inferred from an absence, so it is stated. */
    val deleted: List<DeletedMark>,
    val positions: List<SyncPosition>
)

/** SyncPush is what a client did while it was away. */
@Serializable
data class SyncPush(
    val annotations: List<PushedMark>? = null,
    val positions: List<PushedPosition>? = null
)

/** SyncPushResult says what became of each pushed change. */
@Serializable
data class SyncPushResult(
    val marks: List<MarkResult>
)

/** TOCEntry is one navigation point. */
@Serializable
data class TOCEntry(
    val title: String,
    /** SpineIndex is where the entry points: the spine index for EPUB, the PAGE for PDF - the same thing `major` means in a locator for each format. */
    val spineIndex: Int,
    val fragment: String? = null,
    val children: List<TOCEntry>? = null
)

/** Tag is a label on a work. */
@Serializable
data class Tag(
    val id: String,
    val name: String,
    val slug: String,
    val isSubject: Boolean,
    /** Source says where the tag came from, so the UI can mark machine-generated tags and let the user reject them. */
    val source: String? = null
)

/** TokenRequest asks for a bearer token for a client that is not a browser. */
@Serializable
data class TokenRequest(
    val provider: String? = null,
    val username: String,
    val password: String,
    /** Device names the thing the token is for - "Adam's phone" - and is required. It is how this token is recognised in the session list and revoked, months later, from a device that is no longer to hand. */
    val device: String
)

/** UpdateAnnotation edits a mark's note or colour. The anchor is deliberately not editable: moving a highlight to different text is a different highlight. */
@Serializable
data class UpdateAnnotation(
    val note: String,
    val colour: String? = null
)

/** UpdateWork is a correction somebody made by hand. */
@Serializable
data class UpdateWork(
    val title: String? = null,
    val subtitle: String? = null,
    val series: String? = null,
    val seriesIndex: Double? = null,
    val language: String? = null,
    val description: String? = null,
    /** Authors replaces the whole list, in order. Replacing rather than adding is the point: a book credited to a download site needs that name gone. */
    val authors: List<String>? = null,
    val publisher: String? = null,
    /** Year is the year of publication. Zero clears it. */
    val year: Int? = null,
    val isbn13: String? = null,
    val isbn10: String? = null
)

/** UploadResult is the response to a bulk upload. */
@Serializable
data class UploadResult(
    val files: List<UploadedFile>,
    val summary: UploadSummary,
    /** Interrupted is true when the request ended before every part was read. The listed files are still stored. */
    val interrupted: Boolean? = null,
    val message: String? = null
)

/** UploadStatus is the outcome of one uploaded file. */
@Serializable
enum class UploadStatus {
    @SerialName("stored")
    STORED,
    @SerialName("duplicate")
    DUPLICATE,
    @SerialName("rejected")
    REJECTED
}

/** UploadSummary counts the outcomes. */
@Serializable
data class UploadSummary(
    val stored: Int,
    val duplicate: Int,
    val rejected: Int
)

/** UploadedFile is the per-file outcome of a bulk upload. */
@Serializable
data class UploadedFile(
    val filename: String,
    val status: UploadStatus,
    val contentHash: String? = null,
    val format: String? = null,
    val sizeBytes: Long? = null,
    /** JobID names the extraction job, when one was queued. */
    val jobId: String? = null,
    val error: String? = null,
    /** Code says why a rejected file was rejected, when a client may want to branch on it: "content_blocked" for bytes an administrator has removed from the installation. Empty otherwise. */
    val code: String? = null,
    val note: String? = null
)

/** User is the signed-in account. */
@Serializable
data class User(
    val id: String,
    val username: String,
    val email: String? = null,
    val isAdmin: Boolean,
    /** CanUpload says whether this person may add books by uploading them: administrators always, everybody else when the installation's upload policy allows it. The server decides either way; this is so a client offers the button only where pressing it would work. Omitted when false, so a client built against this field still reads an older server. */
    val canUpload: Boolean? = null,
    /** CanAsk says whether asking the library can work here: a chat model is configured. Without one every question fails, so a client hides its Ask entry points rather than offering a box that cannot answer. It says nothing about whether the model is up right now - that changes by the minute, and an answer that fails says so. Omitted when false. */
    val canAsk: Boolean? = null,
    /** CanListPeople says whether GET /people lists every account for this person: always for an administrator, and for everybody else unless the installation keeps its people unlisted (LEXARII_PEOPLE_DIRECTORY=none), when a client asks for a recipient's username instead of offering a list. Omitted when false. */
    val canListPeople: Boolean? = null,
    val createdAt: String
)

/** WorkDetail is the book detail page. */
@Serializable
data class WorkDetail(
    val id: String,
    val title: String,
    val subtitle: String? = null,
    val sortTitle: String,
    val series: String? = null,
    val seriesIndex: Double? = null,
    val language: String? = null,
    val description: String? = null,
    val summary: String? = null,
    val authors: List<Author>,
    /** Editions carry the publisher, the year and the ISBNs. Written at ingest and, until this page could be corrected, never sent to the client at all - so a book's page showed a title and an author while the record held the rest. */
    val editions: List<Edition>? = null,
    val files: List<BookFile>,
    val tags: List<Tag>? = null,
    /** Warnings are recoverable problems found while parsing: a missing cover, an unreadable TOC, an ignored producer artefact. */
    val warnings: List<String>? = null,
    /** Provenance maps a field name to where its value came from: embedded, user, llm, filename, external. The UI uses this to show what was guessed. */
    val provenance: Map<String, String>? = null,
    val createdAt: String,
    val updatedAt: String
)
